{"explanation":"In y = A sin(B(x − C)) + D, each parameter changes the basic sine wave (the faint gray curve) in its own way. A is the amplitude: it stretches the wave vertically, and a negative A flips it upside down. B sets how often the wave repeats, so the period is 2π/|B|. C is the phase shift, which slides the wave left or right (the yellow dot marks where a cycle starts at x = C). D is the vertical shift, which moves the dashed midline up or down. Use the sliders to change each value, and the readout updates the period, phase shift and midline as you go.","manimCode":"const ax = new Axes({
  xRange: [-2 * Math.PI, 2 * Math.PI, Math.PI / 2],
  yRange: [-5, 5, 1],
  xLength: 9.5, yLength: 6.2, tips: false
});
ax.moveTo([-1.3, -0.4, 0]);
scene.add(ax);

let A = 1, B = 1, C = 0, D = 0;

const ref = ax.plot(x => Math.sin(x), { color: GRAY, xRange: [-2 * Math.PI, 2 * Math.PI] });
ref.setOpacity(0.35);
scene.add(ref);

const formula = new MathTex({ latex: 'y = A\\sin\\big(B(x - C)\\big) + D', color: WHITE });
await formula.waitForRender();
formula.scale(0.8);
formula.moveTo([-1.3, 3.5, 0]);
scene.add(formula);

let curve = null, midline = null, startDot = null, info = null;

function clampY(y) { return Math.max(-5, Math.min(5, y)); }

function redraw() {
  if (curve) scene.remove(curve);
  if (midline) scene.remove(midline);
  if (startDot) scene.remove(startDot);
  if (info) scene.remove(info);

  midline = new DashedLine({
    start: ax.c2p(-2 * Math.PI, clampY(D)),
    end: ax.c2p(2 * Math.PI, clampY(D)),
    color: GREEN
  });

  curve = ax.plot(x => clampY(A * Math.sin(B * (x - C)) + D), {
    color: BLUE, xRange: [-2 * Math.PI, 2 * Math.PI], numSamples: 800
  });

  startDot = new Dot({ point: ax.c2p(C, clampY(D)), color: YELLOW });

  const period = (2 * Math.PI / Math.abs(B)).toFixed(2);
  info = new Text({
    text: 'A=' + A.toFixed(1) + '  B=' + B.toFixed(1) + '  C=' + C.toFixed(2) + '  D=' + D.toFixed(1) +
      '    period=' + period + '  amplitude=' + Math.abs(A).toFixed(1),
    color: YELLOW, fontSize: 20
  });
  info.moveTo([-1.3, -3.75, 0]);

  scene.add(midline, curve, startDot, info);
}

redraw();

const controls = new Controls(scene, { position: 'top-right', width: 240 });
controls.addSlider({ label: 'A (amplitude)', min: -4, max: 4, value: 1, step: 0.1, onChange: v => { A = v; redraw(); } });
controls.addSlider({ label: 'B (frequency)', min: 0.1, max: 4, value: 1, step: 0.1, onChange: v => { B = v; redraw(); } });
controls.addSlider({ label: 'C (phase shift)', min: -Math.PI, max: Math.PI, value: 0, step: 0.05, onChange: v => { C = v; redraw(); } });
controls.addSlider({ label: 'D (vertical shift)', min: -3, max: 3, value: 0, step: 0.1, onChange: v => { D = v; redraw(); } });

await scene.wait(999999);"}

